SYMPY_EXT_HELP = [
    "# sympy_ext - توسعة حزمة sympy: أصنافها ودوالها وطرقها وثوابتها التي لا تغطّيها مكتبات APL الأخرى",
]

_SYMPY_EXT_TOKEN = re.compile(
    r"(?P<dot>\.)?"
    r"(?P<word>(?!\d)[\w\u064B-\u065F\u0670]+)"
    r"(?P<open>\s*\()?"
)

USER_NAMES = set()


def _sympy_ext_replace(match):
    dot = match.group("dot")
    word = match.group("word")
    open_paren = match.group("open")
    if word in USER_NAMES:
        return match.group(0)
    if dot:
        return match.group(0)
    if word in SYMPY_EXT_CONSTS:
        return SYMPY_EXT_CONSTS[word]
    if word in SYMPY_EXT_FUNCS:
        return SYMPY_EXT_FUNCS[word] + (open_paren or "")
    return match.group(0)


def SYMPY_EXT_SUBSTITUTE(text):
    """يترجم كلمات المكتبة في نص واحد ويُرجع المترجم."""
    if not text:
        return text
    return _SYMPY_EXT_TOKEN.sub(_sympy_ext_replace, text)
